from pathlib import Path
path=Path(__file__).with_name('index.html')
s=path.read_text()
s=s.replace("import {validateProject} from './project-validation.mjs';", "import {validateProject} from './project-validation.mjs';\nimport {scoreBreakdown,weightsAt,sensitivityThresholds,compareScenarios,robustness,projectionFront} from './advanced-analytics.mjs';")
s=s.replace('weightAdjustment:null});','weightAdjustment:null,scenarios:[]});')
s=s.replace('validateProject(p);}catch{p=newProject();}', 'validateProject(p);p.scenarios??=[];}catch{p=newProject();}')
s=s.replace('value="${esc(p.scores[c.id]?.[a.id]??0)}"','value="${esc(p.scores[c.id]?.[a.id]??\'\')}"')
# results view add extra panel
needle="out+='</section>';\n out+=`<section class=\"card\"><h2>Trade-offs"
assert needle in s
s=s.replace(needle,"out+='</section>';out+=advancedView(results);\n out+=`<section class=\"card\"><h2>Trade-offs" )
insert=r'''
function advancedView(results){if(!results)return '';const namesMap=Object.fromEntries(p.alternatives.map(a=>[a.id,a.name]));const ids=p.alternatives.map(a=>a.id),w=results.weights,cols=results.columns;
const breakdown=scoreBreakdown(w,cols,ids),max=Math.max(...breakdown.map(x=>x.score));let out=`<section class="card"><h2>Advanced analytics</h2><p>Exact one-at-a-time weight thresholds, saved weighting scenarios, deterministic simulation and transparent score contributions. Simulated stability is not a probability of real-world success.</p><h3>Weighted contributions</h3><div class="table-scroll"><table><thead><tr><th>Alternative</th>${p.criteria.map(c=>`<th>${esc(c.name)}</th>`).join('')}<th>Total</th></tr></thead><tbody>${breakdown.map(b=>`<tr><td>${esc(namesMap[b.id])}</td>${b.contributions.map(x=>`<td>${(100*x).toFixed(2)}%</td>`).join('')}<td><strong>${(100*b.score).toFixed(2)}%</strong></td></tr>`).join('')}</tbody></table></div>`;
const idx=Math.min(analyticsCriterion,p.criteria.length-1);let sensitivity=sensitivityThresholds(w,cols,idx,ids);out+=`<h3>Exact winner-switch sensitivity</h3><div class="row"><label>Adjust one criterion (others proportionally redistributed)<select id="thresholdCriterion">${options(p.criteria,p.criteria[idx].id)}</select></label></div><p>Winner across intervals of ${esc(p.criteria[idx].name)} weight:</p><div class="table-scroll"><table><thead><tr><th>Weight range</th><th>Highest-ranked alternative(s)</th></tr></thead><tbody>${sensitivity.intervals.map(t=>`<tr><td>${(t.from*100).toFixed(2)}% – ${(t.to*100).toFixed(2)}%</td><td>${t.winners.map(id=>esc(namesMap[id])).join(', ')}</td></tr>`).join('')}</tbody></table></div><p class="muted">Calculated by exact line intersections for this fixed set of alternative priorities. At a boundary, multiple alternatives can tie. Does not model changes to pairwise judgments.</p>`;
let scenarios=(p.scenarios??[]);out+=`<h3>Saved weighting scenarios</h3><div class="row"><input type="text" id="scenarioName" maxlength="100" placeholder="Scenario name, e.g. Cost focused"><button id="saveScenario" ${scenarios.length>=12?'disabled':''}>Save current weights</button></div>`;
if(scenarios.length){const comparison=compareScenarios(scenarios,cols,ids);out+=`<div class="table-scroll"><table><thead><tr><th>Scenario</th><th>Top alternative(s)</th><th>Weights</th><th>Action</th></tr></thead><tbody>${comparison.map((sc,i)=>`<tr><td>${esc(sc.name)}</td><td>${sc.results.filter(r=>sc.results[0].score-r.score<1e-10).map(r=>esc(namesMap[r.id])).join(', ')}</td><td>${sc.weights.map((x,j)=>`${esc(p.criteria[j].name)} ${(100*x).toFixed(1)}%`).join(' · ')}</td><td><button data-load-scenario="${i}">Apply</button> <button class="danger" data-remove-scenario="${i}">Delete</button></td></tr>`).join('')}</tbody></table></div>`;}
out+=`<h3>Ranking robustness (Monte Carlo)</h3><div class="row"><label>Weight perturbation<select id="robustRange"><option value="0.1" ${analyticsRange===.1?'selected':''}>±10%</option><option value="0.2" ${analyticsRange===.2?'selected':''}>±20%</option><option value="0.4" ${analyticsRange===.4?'selected':''}>±40%</option></select></label><span class="muted">2,000 reproducible samples · fixed random seed</span></div>`;
const sim=robustness(w,cols,ids,{relativeRange:analyticsRange,samples:2000,seed:2026});out+=`<div class="table-scroll"><table><thead><tr><th>Alternative</th><th>First-place share</th><th>Mean rank</th></tr></thead><tbody>${sim.results.map(r=>`<tr><td>${esc(namesMap[r.id])}</td><td>${(100*r.firstShare).toFixed(1)}%</td><td>${r.meanRank.toFixed(2)}</td></tr>`).join('')}</tbody></table></div><p class="muted">Each criterion weight is independently multiplied by a uniform random factor in the indicated range, then all weights are renormalised. These are simulation frequencies, not confidence levels; structural zero weights remain zero. First-place ties share credit. Average rank breaks ties by the fixed input order.</p></section>`;return out;}
let analyticsCriterion=0,analyticsRange=.2;
'''
s=s.replace('function renderFrontier(){',insert+'\nfunction renderFrontier(){')
# replace sensitivity handler with mathematical function
old="const i=Number(el.dataset.sens),raw=p.weightAdjustment??getWeights(),desired=Number(el.value)/100,rest=1-raw[i];p.weightAdjustment=raw.length===1?[1]:raw.map((v,j)=>j===i?desired:rest>0?v*(1-desired)/rest:(1-desired)/(raw.length-1));if(raw.length===1)p.weightAdjustment=[1];"
assert old in s
s=s.replace(old,"const i=Number(el.dataset.sens),raw=p.weightAdjustment??getWeights(),desired=Number(el.value)/100;p.weightAdjustment=weightsAt(raw,i,desired);")
needle="if($('resetSensitivity'))$('resetSensitivity').onclick=()=>update(()=>p.weightAdjustment=null);"
assert needle in s
s=s.replace(needle,needle+"if($('thresholdCriterion'))$('thresholdCriterion').onchange=el=>{analyticsCriterion=p.criteria.findIndex(c=>c.id===el.target.value);render();};if($('robustRange'))$('robustRange').onchange=el=>{analyticsRange=Number(el.target.value);render();};if($('saveScenario'))$('saveScenario').onclick=()=>{const name=$('scenarioName').value.trim();if(!name){alert('Enter a scenario name');return;}update(()=>{p.scenarios??=[];if(p.scenarios.length>=12)throw Error('Scenario limit');p.scenarios.push({name,weights:[...(p.weightAdjustment??getWeights())],criteriaIds:p.criteria.map(c=>c.id)});});};document.querySelectorAll('[data-load-scenario]').forEach(el=>el.onclick=()=>update(()=>{p.weightAdjustment=[...p.scenarios[Number(el.dataset.loadScenario)].weights];}));document.querySelectorAll('[data-remove-scenario]').forEach(el=>el.onclick=()=>update(()=>{p.scenarios.splice(Number(el.dataset.removeScenario),1);}));")
# if structure edits invalidate scenario snapshots (use id matching instead in validation)
s=s.replace('p.criteriaComparisons={};p.weightAdjustment=null;', 'p.criteriaComparisons={};p.weightAdjustment=null;p.scenarios=[];')
s=s.replace('p.criteriaComparisons={};p.weightAdjustment=null;});', 'p.criteriaComparisons={};p.weightAdjustment=null;p.scenarios=[];});')
# fixed ax scatter should show projection warning for full efficient -> use new projection analysis
s=s.replace("const ranked=paretoFront(pts,directions);const efficient=ranked.filter(r=>r.efficient).length;", "const ranked=paretoFront(pts,directions);const efficient=ranked.filter(r=>r.efficient).length;")
s=s.replace("const xv=pts.map(z=>z.objectives[x.id])", "const projected=projectionFront(pts,directions,x.id,y.id);const mismatch=projected.filter(z=>z.efficientAll!==z.efficient2D).length;const xv=pts.map(z=>z.objectives[x.id])")
s=s.replace("html+=`<svg id=\"chart\"", "html+=`<p class=\"muted\">${mismatch} alternative(s) have different Pareto status in the selected 2D projection versus the full ${p.objectives.length}-objective analysis.</p><svg id=\"chart\"")
path.write_text(s)
# validation extension
vpath=Path(__file__).with_name('project-validation.mjs');v=vpath.read_text();v=v.replace('  return p;','''  if(p.scenarios!==undefined){if(!Array.isArray(p.scenarios)||p.scenarios.length>12)fail('scenarios count');for(const s of p.scenarios){if(!object(s)||typeof s.name!=='string'||!s.name.trim()||s.name.length>100||!Array.isArray(s.criteriaIds)||s.criteriaIds.length!==p.criteria.length||s.criteriaIds.some((id,i)=>id!==p.criteria[i].id)||!Array.isArray(s.weights)||s.weights.length!==p.criteria.length||s.weights.some(x=>!finite(x)||x<0)||Math.abs(s.weights.reduce((a,b)=>a+b,0)-1)>1e-8)fail('scenario data')}}
  return p;''');vpath.write_text(v)
